      "text": "Added the type “ton_address” to the class MessageEntity for addresses in the TON blockchain."
    },
    {
      "version": "10.4",
      "date": "November 9, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#november-9-2026",
      "text": "Added the type “bank_card_number” to the class MessageEntity for bank card numbers."
    },
    {
      "version": "9.5",
      "date": "March 1, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#march-1-2026",
      "text": "Added the MessageEntity type “date_time”, allowing bots to show a formatted date and time to the user."
    },
    {
